// Source: pantry.js
(() => {
  'use strict';
  function connect(state){
    const farms=state.farms||{},home=farms.willow;if(!home)return;
    const basket=home.inventory||state.inventory||{};
    if(!state.sharedPantryVersion){
      // Eastbank and Back Pasture already shared Willow's basket. JSON restores
      // contain copies of that basket, which must never be counted again.
      const seen=new Set([basket]);
      for(const [id,f] of Object.entries(farms)){
        if(['willow','east','back'].includes(id)||!f.inventory||seen.has(f.inventory))continue;
        seen.add(f.inventory);
        for(const [k,n] of Object.entries(f.inventory))if(Number.isFinite(n)&&n>0&&k!=='__proto__')basket[k]=(Number(basket[k])||0)+Math.floor(n);
      }
      state.sharedPantryVersion=1;
    }
    state.inventory=basket;for(const f of Object.values(farms))f.inventory=basket;
    return basket;
  }
  function canDeliver(order,basket){return Object.entries(order.ask||{}).every(([k,n])=>(basket[k]||0)>=n)}
  function deliver(farm,id){const i=farm.orders.findIndex(o=>o.id===id);if(i<0)return null;const o=farm.orders[i];if(!canDeliver(o,farm.inventory))return null;for(const[k,n]of Object.entries(o.ask))farm.inventory[k]-=n;farm.orders.splice(i,1);return o}
  window.meadowPantry={connect,canDeliver,deliver};
})();

// Source: animal-bonds.js
(() => {
  'use strict';
  const thresholds=[0,3,9,18,30],names=['New friend','Getting to know you','Farm companion','Trusted friend','Best farm friend'],cooldown=600000;
  function points(a){return Math.max(0,Math.floor(Number(a.friendship?.points)||0))}
  function rank(a){const n=points(a);let level=1;for(let i=1;i<thresholds.length;i++)if(n>=thresholds[i])level=i+1;return level}
  function bonus(a){return rank(a)>=5?2:rank(a)>=3?1:0}
  function wait(a,kind,now=Date.now()){const last=Number(a.friendship?.last?.[kind]);return Number.isFinite(last)?Math.max(0,last+cooldown-now):0}
  function record(a,action,before={},now=Date.now()){
    const kinds=action==='all'?['feed','brush','play'].filter(k=>Number(before[{feed:'hunger',brush:'clean',play:'happy'}[k]])<90):action==='treat'?['feed']:['feed','brush','play'].includes(action)?[action]:[];
    let earned=0;for(const kind of kinds){if(wait(a,kind,now)>0||rank(a)===5)continue;a.friendship ||= {points:0,last:{}};a.friendship.last ||= {};a.friendship.points=points(a)+1;a.friendship.last[kind]=now;earned++}return earned;
  }
  function description(a,now=Date.now()){
    const level=rank(a),n=points(a),extra=bonus(a),next=thresholds[level],waiting=['feed','brush','play'].map(k=>wait(a,k,now)),seconds=Math.ceil(Math.min(...waiting)/1000);
    return {level,name:names[level-1],points:n,bonus:extra,next,needed:next?next-n:0,seconds};
  }
  function card(a){const d=description(a);return '<div class="task-card animal-bond-card"><small class="eyebrow">YOUR FRIENDSHIP · LEVEL '+d.level+' / 5</small><h3>'+d.name+'</h3><p>'+Array.from({length:5},(_,i)=>i<d.level?'♥':'♡').join(' ')+'</p><p class="sheet-copy">'+(d.next?d.points+' / '+d.next+' care stars · '+d.needed+' to the next level.':'A wonderful friendship, saved with your farm.')+' '+(d.bonus?'Adds '+d.bonus+' extra '+(d.bonus===1?'good':'goods')+' to every happy collection.':'At level 3, friendship adds an extra product to every happy collection.')+'</p><small class="sheet-copy" id="animal-bond-timer">'+timing(a)+'</small></div>'}
  function timing(a){const d=description(a);return d.level===5?'Best friends · +2 goods per collection':d.seconds?'Next care star in '+Math.ceil(d.seconds/60)+' minutes.':'Feed, brush or play to earn care stars. Each activity earns one star every 10 minutes.'}
  window.meadowBonds={thresholds,rank,points,bonus,wait,record,description,card,timing};
})();

// Source: crop-growth.js
(() => {
  'use strict';
  const clamp=n=>Math.max(0,Math.min(1,n));
  function near(plot,flower){const side=Math.max(1,Math.min(4,1+Math.floor(Number(plot.tier)||0))),dx=Math.max(plot.x-flower.x,0,flower.x-(plot.x+side-1)),dy=Math.max(plot.y-flower.y,0,flower.y-(plot.y+side-1));return dx+dy<=4}
  function calculate(p,crop,objects,now=Date.now()){
    if(!p.plantedAt)return {progress:0,stage:p.stage||0,bonusMs:0,remainingMs:0};
    const duration=Math.max(1,Number(crop.time)*3),from=Math.max(p.plantedAt,Number(p.growthSettledAt)||p.plantedAt),flowers=objects.filter(f=>f.type==='flowers'&&Number(f.plantedAt)>0&&near(p,f)),starts=flowers.map(f=>f.plantedAt+240000),active=starts.filter(t=>t<=now),start=active.length?Math.max(from,Math.min(...active)):now,bonusMs=Math.max(0,Number(p.growthBonusMs)||0)+Math.max(0,now-start)*.18,elapsed=Math.max(0,now-p.plantedAt)+bonusMs,progress=clamp(elapsed/duration),work=Math.max(0,duration-elapsed),next=starts.filter(t=>t>now).sort((a,b)=>a-b)[0];
    const remainingMs=active.length?work/1.18:next&&work>next-now?(next-now)+(work-(next-now))/1.18:work;
    return {progress,stage:progress>=1?3:progress<.2?0:progress<.48?1:2,bonusMs,remainingMs};
  }
  function settle(farm,items,now=Date.now()){const flowers=farm.objects.filter(o=>o.type==='flowers');for(const p of farm.objects.filter(o=>o.type==='plot'&&o.plantedAt)){const g=calculate(p,items[p.crop]||items.carrot,flowers,now);p.growthBonusMs=g.bonusMs;p.growthSettledAt=now}}
  function start(p,id,now=Date.now()){p.crop=id;p.plantedAt=now;p.stage=1;p.wateredUntil=0;p.growthBonusMs=0;p.growthSettledAt=now}
  window.meadowCropGrowth={calculate,settle,start,near};
})();

// Source: crop-mastery.js
(() => {
 'use strict';
 const crops=['carrot','wheat','strawberry','corn','tomato','lavender','pumpkin','mushroom'];
 const ranks=[{tiles:0,name:'Learning the rows',discount:0,bonus:0},{tiles:20,name:'Seed saver',discount:5,bonus:0},{tiles:80,name:'Skilled grower',discount:5,bonus:1},{tiles:200,name:'Meadow expert',discount:10,bonus:1},{tiles:500,name:'Master grower',discount:10,bonus:2}];
 let api;
 const finite=n=>Number.isFinite(Number(n))?Math.max(0,Math.min(1000000000,Math.floor(Number(n)))):0;
 function tiles(state,id){return crops.includes(id)?finite(state.cropMastery?.tiles?.[id]):0}
 function status(state,id){const count=tiles(state,id);let rank=0;for(let i=1;i<ranks.length;i++)if(count>=ranks[i].tiles)rank=i;const next=ranks[rank+1];return {...ranks[rank],rank:rank+1,count,next,progress:next?(count-ranks[rank].tiles)/(next.tiles-ranks[rank].tiles):1}}
 function record(state,id,area){if(!crops.includes(id)||!Number.isInteger(area)||area<1||area>16)return null;const before=status(state,id);state.cropMastery||={tiles:{}};state.cropMastery.tiles||={};state.cropMastery.tiles[id]=Math.min(1000000000,before.count+area);return {before,after:status(state,id)}}
 function bonus(state,id){return status(state,id).bonus}
 function seedCost(state,id,base){if(!Number.isFinite(base)||base<0)return 0;return Math.ceil(base*(100-status(state,id).discount)/100)}
 function benefits(r){return [r.discount?r.discount+'% cheaper seeds':'',r.bonus?'+'+r.bonus+' crop'+(r.bonus>1?'s':'')+' per tile':''].filter(Boolean).join(' · ')||'Harvest to grow your skill'}
 function card(id,state){const r=status(state,id),name=api.items[id].name;return '<button class="mastery-card" data-mastery-crop="'+id+'"><span class="book-plant"><img src="assets/generated/crop-growth/'+id+'.webp" alt=""></span><strong>'+name+'</strong><span class="mastery-rank">Rank '+r.rank+' · '+r.name+'</span><progress value="'+r.progress+'" max="1" aria-label="'+name+' mastery progress"></progress><small>'+r.count.toLocaleString()+' tile'+(r.count===1?'':'s')+' harvested'+(r.next?' · '+(r.next.tiles-r.count).toLocaleString()+' to rank '+(r.rank+1):' · mastered')+'</small><small>'+benefits(r)+'</small></button>'}
 function show(id){
  const state=api.state(),chosen=crops.includes(id)?id:null,r=chosen?status(state,chosen):null;
  api.modal('<div class="sheet-head mastery-head"><div><small class="eyebrow">FARMER JADE’S GROWING NOTES</small><h2>'+(chosen?api.items[chosen].name+' mastery':'Crop mastery')+'</h2></div><button class="small-button mastery-listen" id="mastery-listen" aria-label="Farmer Jade: crop mastery">🔊</button><button class="close-button" data-close="modal-dialog">×</button></div><details class="flow-details"><summary>How mastery works</summary><p class="sheet-copy">Each harvested tile earns one point. Farmer Jade’s harvests count across every farm; bought goods and mini-game prizes do not.</p></details>'+(chosen?'<div class="mastery-focus">'+card(chosen,state)+'</div><div class="mastery-steps">'+ranks.map((step,i)=>'<div class="mastery-step '+(r.rank>i?'mastery-earned':'')+'"><strong>'+(r.rank>i?'✓ ':'')+'Rank '+(i+1)+' · '+step.name+'</strong><small>'+step.tiles+' tiles harvested</small><span>'+benefits(step)+'</span></div>').join('')+'</div><button class="primary-button full-button" id="mastery-grow">Find where to grow '+api.items[chosen].name.toLowerCase()+'</button><button class="soft-link full-button" id="mastery-all">All crops</button>':'<div class="mastery-grid">'+crops.map(id=>card(id,state)).join('')+'</div>')+'<small class="sheet-copy">Progress starts with harvests after this update. Perks apply automatically. Seed savings round up to whole gold; bonus crops are added to the field and watering yield.</small>');
  document.querySelector('#mastery-listen').onclick=()=>window.meadowAudio?.speak('jade-crop-mastery128');
  document.querySelectorAll('[data-mastery-crop]').forEach(b=>b.onclick=()=>show(b.dataset.masteryCrop));
  document.querySelector('#mastery-grow')?.addEventListener('click',()=>api.find(chosen));
  document.querySelector('#mastery-all')?.addEventListener('click',()=>show());
  if(!state.cropMasteryHeard128){state.cropMasteryHeard128=true;api.save();window.meadowAudio?.speak('jade-crop-mastery128')}
 }
 window.meadowMastery={crops,ranks,tiles,status,record,bonus,seedCost,benefits,show,attach(a){api=a}};
})();

