    $('#shop-name-save').onclick=()=>{const name=Array.from($('#shop-name').value.trim()).slice(0,28).join('');if(!name){api.notify('Give your shop a name first');return}s.name=name;api.save();renderShop();api.notify('Shop name saved')};
